D=Path('/mnt/e/skillpilot-chemie-L7-20261017/arrhenius-and-HE-practice-retained-target-scope-author-v1')
def digest(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def pin(p): return {'path':str(p),'sha256':digest(p),'bytes':Path(p).stat().st_size}
def write(n,v):
 p=O/n
 if p.exists(): raise RuntimeError('Immutable own result exists: '+str(p))
 p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
 return pin(p)
